using System.Net; using System.Security.Cryptography; using System.Text; using System.Text.Json; using Microsoft.EntityFrameworkCore;
namespace CoffeeControl.Api;
public sealed class TelegramAuth(IConfiguration config)
{ public async Task<User?> AuthenticateAsync(HttpRequest request, AppDbContext db, CancellationToken ct) { var init=request.Headers["X-Telegram-Init-Data"].FirstOrDefault(); var token=config["TELEGRAM_BOT_TOKEN"]; if(string.IsNullOrWhiteSpace(init)) { if(string.Equals(config["ASPNETCORE_ENVIRONMENT"],"Development",StringComparison.OrdinalIgnoreCase)) return await GetOrCreateAsync(db,999999,"dev","Разработчик",ct); return null; } if(string.IsNullOrWhiteSpace(token)) return null;
   Dictionary<string,string> parts; try { parts=init.Split('&',StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split('=',2)).Where(x=>x.Length==2).ToDictionary(x=>WebUtility.UrlDecode(x[0]),x=>WebUtility.UrlDecode(x[1])); } catch(ArgumentException) { return null; }
   var now=DateTimeOffset.UtcNow.ToUnixTimeSeconds(); if(!parts.TryGetValue("hash",out var hash)||!parts.TryGetValue("auth_date",out var stamp)||!long.TryParse(stamp,out var unix)||unix>now+60||now-unix>86400)return null; var check=string.Join('\n',parts.Where(x=>x.Key!="hash").OrderBy(x=>x.Key).Select(x=>$"{x.Key}={x.Value}")); using var h= new HMACSHA256(Encoding.UTF8.GetBytes("WebAppData")); var secret=h.ComputeHash(Encoding.UTF8.GetBytes(token)); var expected=Convert.ToHexString(new HMACSHA256(secret).ComputeHash(Encoding.UTF8.GetBytes(check))).ToLowerInvariant(); if(hash.Length!=expected.Length||!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(expected),Encoding.UTF8.GetBytes(hash.ToLowerInvariant())))return null; if(!parts.TryGetValue("user",out var json))return null; try { using var doc=JsonDocument.Parse(json); var u=doc.RootElement; return await GetOrCreateAsync(db,u.GetProperty("id").GetInt64(),u.TryGetProperty("username",out var un)?un.GetString():null,u.TryGetProperty("first_name",out var fn)?fn.GetString()??"Бариста":"Бариста",ct); } catch(JsonException) { return null; } catch(KeyNotFoundException) { return null; } }
 private async Task<User?> GetOrCreateAsync(AppDbContext db,long id,string? username,string first,CancellationToken ct){var admin=(config["ADMIN_TELEGRAM_IDS"]??"").Split(',',StringSplitOptions.RemoveEmptyEntries).Select(x=>long.TryParse(x.Trim(),out var value)?(long?)value:null).OfType<long>().Contains(id); var u=await db.Users.SingleOrDefaultAsync(x=>x.TelegramId==id,ct); if(u is null){u=new User{TelegramId=id,Username=username,FirstName=first,Role=admin?Role.Admin:Role.Barista};db.Users.Add(u);} else {if(!u.IsActive)return null;u.LastLoginAt=DateTime.UtcNow;u.Username=username;} await db.SaveChangesAsync(ct); return u; }
}
